/*
 * model_test.c - minimal viewer for the model pipeline.
 * Shows the ORIGINAL test character loaded through src/model.c (NMDL + NMTX).
 * Loads from assets/chr/test/ next to the EBOOT if present, otherwise from the
 * copy embedded in the EBOOT (src/gen_assets.c, generated by tools/).
 */
#include <pspkernel.h>
#include <pspctrl.h>
#include <pspdisplay.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "gfx.h"
#include "model.h"

extern const unsigned char test_character_nmdl[];
extern const unsigned int test_character_nmdl_size;
extern const unsigned char test_character_nmtx[];
extern const unsigned int test_character_nmtx_size;

#define MODEL_FILE "assets/chr/test/test_character.nmdl"
#define TEX_FILE   "assets/chr/test/test_texture.nmtx"

int model_test_run(void)
{
    Model m;
    ModelTexture tex;
    const char *msrc = "FILE", *tsrc = "FILE";
    int mr, tr, use_tex = 1, spin = 1;
    float yaw = 0.0f;
    unsigned prev = 0, pressed;
    SceCtrlData pad;
    char line[64];

    gfx_init();
    sceCtrlSetSamplingCycle(0);
    sceCtrlSetSamplingMode(PSP_CTRL_MODE_ANALOG);

    mr = model_load(&m, MODEL_FILE);
    if (mr < 0) {
        mr = model_load_memory(&m, test_character_nmdl, test_character_nmdl_size);
        msrc = "EMBEDDED";
    }
    tr = model_texture_load(&tex, TEX_FILE);
    if (tr < 0) {
        tr = model_texture_load_memory(&tex, test_character_nmtx, test_character_nmtx_size);
        tsrc = "EMBEDDED";
    }

    for (;;) {
        sceCtrlPeekBufferPositive(&pad, 1);
        pressed = pad.Buttons & ~prev;
        prev = pad.Buttons;
        if (pressed & PSP_CTRL_CROSS) yaw = 0.0f;
        if (pressed & PSP_CTRL_START) spin = !spin;
        if (pressed & PSP_CTRL_TRIANGLE) use_tex = !use_tex;
        if (pressed & PSP_CTRL_SQUARE) spin = !spin;
        if (pad.Buttons & PSP_CTRL_LEFT)  yaw -= 0.05f;
        if (pad.Buttons & PSP_CTRL_RIGHT) yaw += 0.05f;
        if (spin) yaw += 0.015f;

        gfx_begin(RGB(30, 40, 70));
        gfx_2d();
        gfx_gradient(0, 0, 480, 272, RGB(25, 35, 80), RGB(90, 70, 110));
        gfx_3d();
        gfx_camera(0.0f, 1.05f, 2.85f, 0.0f, 0.83f, 0.0f);
        gfx_box(0.0f, -0.05f, 0.0f, 3.2f, 0.1f, 3.2f, RGB(70, 80, 110));
        if (mr == 0) {
            if (use_tex && tr == 0) model_draw_textured(&m, &tex, 0.0f, 0.0f, 0.0f, yaw);
            else model_draw(&m, 0.0f, 0.0f, 0.0f, yaw);
        }

        gfx_2d();
        gfx_text(10, 8, 2, RGB(255, 220, 100), "CHARACTER MODEL VIEWER - 1.66M TARGET");
        if (mr == 0) {
            sprintf(line, "MESH: %s  %u TRIANGLES", msrc, m.vertex_count / 3);
            gfx_text(10, 30, 1, RGB(200, 230, 255), line);
        } else {
            sprintf(line, "MODEL LOAD FAILED: CODE %d", mr);
            gfx_text(10, 30, 1, RGB(255, 100, 100), line);
        }
        if (tr == 0) sprintf(line, "TEXTURE: %s %ux%u %s", tsrc, tex.width, tex.height, use_tex ? "ON" : "OFF");
        else sprintf(line, "TEXTURE LOAD FAILED: CODE %d", tr);
        gfx_text(10, 42, 1, RGB(200, 230, 255), line);
        gfx_text(10, 240, 1, RGB(220, 220, 220), "LEFT/RIGHT: ROTATE   SQUARE: SPIN   START: AUTO ROTATE");
        gfx_text(10, 254, 1, RGB(255, 220, 100), "CROSS: RESET VIEW   (GAME MENU DISABLED)");
        gfx_end();
    }

    model_free(&m);
    model_texture_free(&tex);
    return 0;
}
